 40→// ---------------------------------------------------------------------------
 41→// Types
 42→// ---------------------------------------------------------------------------
 43→
 44→type FeatureRequestRecord = {
 45→  id: string;
 46→  title: string;
 47→  description: string;
 48→  category: string;
 49→  status: string;
 50→  shop: string;
 51→  votesCount: number;
 52→  createdAt: string | Date;
 53→  updatedAt: string | Date;
 54→};
 55→
 56→type VoteResult = {
 57→  success: true;
 58→  intent: "vote";
 59→  featureId: string;
 60→  newCount: number;
 61→  voted: boolean;
 62→};
 63→type SubmitResult = { success: true; intent: "submit" };
 64→type DeleteResult = { success: true; intent: "delete" };
 65→type StatusResult = { success: true; intent: "update-status" };
 66→type EditResult = { success: true; intent: "edit" };
 67→type ErrorResult = { error: string };
 68→
 69→type ActionResult =
 70→  | VoteResult
 71→  | SubmitResult
 72→  | DeleteResult
 73→  | StatusResult
 74→  | EditResult
 75→  | ErrorResult;
 76→
 77→// ---------------------------------------------------------------------------
 78→// Constants
 79→// ---------------------------------------------------------------------------
 80→
 81→const VALID_CATEGORIES = new Set([
 82→  "General",
 83→  "UI & Design",
 84→  "Data & Export",
 85→  "API & Integration",
 86→  "Performance",
 87→  "Billing",
 88→]);
 89→
